const http = require('http');

// Read environment variables from .env.test
const envFile = require('fs').readFileSync('.env.test', 'utf8');

// Parse the file
const envVars = {};
const lines = envFile.split('\n');
for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const firstEquals = trimmed.indexOf('=');
    if (firstEquals !== -1) {
        const key = trimmed.substring(0, firstEquals);
        const value = trimmed.substring(firstEquals + 1);
        envVars[key] = value;
    }
}

// Create payload
const payload = {
  source_file: ".env.test",
  environment_variables: envVars,
  count: Object.keys(envVars).length,
  timestamp: new Date().toISOString()
};

const postData = JSON.stringify(payload);

// Make POST request
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });
  res.on('end', () => {
    console.log('Success! Response:', responseData);
  });
});

req.on('error', (err) => {
  console.error('Error connecting to API:', err.message);
});

req.write(postData);
req.end();

EOF

