    gsub(/#.*/, "", key)
    sub(/^ */, "", key)
    gsub(/ *$/, "", key)

    value=$2
    # Remove comments from value
    gsub(/#.*/, "", value)

    if (key && value) {
        printf "\"%s\": \"%s\"\n", key, value
    }
}' > env_vars.json && cat env_vars.json

